using Microsoft.SemanticKernel;
using Azure.Identity;

var builder = WebApplication.CreateBuilder(args);

// 1. Add Azure OpenAI Chat Completion service to DI
builder.Services.AddAzureOpenAIChatCompletion(
    deploymentName: builder.Configuration["AzureOpenAI:ChatDeployment"] ?? "gpt-4o",
    endpoint: builder.Configuration["AzureOpenAI:Endpoint"]!,
    credential: new DefaultAzureCredential());

// 2. Add Kernel to DI with automatic service injection
builder.Services.AddKernel();

// 3. Inject Kernel into consumer services
public class CustomerSupportAssistant
{
    private readonly Kernel _kernel;

    public CustomerSupportAssistant(Kernel kernel)
    {
        _kernel = kernel;
    }

    public async Task<string> AnswerInquiryAsync(string userQuestion, CancellationToken ct = default)
    {
        var prompt = $"You are a helpful customer support assistant.\nUser Question: {userQuestion}";
        var result = await _kernel.InvokePromptAsync(prompt, cancellationToken: ct);
        return result.GetValue<string>() ?? string.Empty;
    }
}

using Microsoft.SemanticKernel;

public class LoggingFunctionInvocationFilter : IFunctionInvocationFilter
{
    private readonly ILogger<LoggingFunctionInvocationFilter> _logger;

    public LoggingFunctionInvocationFilter(ILogger<LoggingFunctionInvocationFilter> logger)
    {
        _logger = logger;
    }

    public async Task OnFunctionInvocationAsync(
        FunctionInvocationContext context,
        Func<FunctionInvocationContext, Task> next)
    {
        var pluginName = context.Function.PluginName;
        var functionName = context.Function.Name;

        _logger.LogInformation("Invoking function {Plugin}.{Function}", pluginName, functionName);
        var sw = Stopwatch.StartNew();

        try
        {
            // Continue execution pipeline
            await next(context);
            sw.Stop();
            _logger.LogInformation("Function {Plugin}.{Function} succeeded in {ElapsedMs}ms",
                pluginName, functionName, sw.ElapsedMilliseconds);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Function {Plugin}.{Function} failed", pluginName, functionName);
            throw;
        }
    }
}

// In Program.cs: Register filter in DI
builder.Services.AddSingleton<IFunctionInvocationFilter, LoggingFunctionInvocationFilter>();
